public class FitnessFunction_value_TriageGen0Test {

    private CMAESOptimizer.FitnessFunction fitnessFunction;
    private CMAESOptimizer mockOptimizer;

    @Before
    public void setUp() throws Exception {
        // Since FitnessFunction is an inner class of CMAESOptimizer, 
        // we need an instance of the outer class.
        mockOptimizer = mock(CMAESOptimizer.class);
        fitnessFunction = spy(new CMAESOptimizer.FitnessFunction());

        // Inject the outer class instance into the inner class using reflection 
        // because the code uses CMAESOptimizer.this
        Field outerField = CMAESOptimizer.FitnessFunction.class.getDeclaredField("this$0");
        outerField.setAccessible(true);
        outerField.set(fitnessFunction, mockOptimizer);
    }

    private void setField(String fieldName, Object value) throws Exception {
        Field field = CMAESOptimizer.FitnessFunction.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(fitnessFunction, value);
    }

    @Test
    public void testValue_NoBoundaries_Minimize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] decoded = {1.0, 2.0};
        double objectiveValue = 10.0;

        setField("boundaries", null);
        setField("isRepairMode", false);
        setField("isMinimize", true);

        doReturn(decoded).when(fitnessFunction).decode(point);
        when(mockOptimizer.computeObjectiveValue(decoded)).thenReturn(objectiveValue);

        double result = fitnessFunction.value(point);

        assertEquals(objectiveValue, result, 1e-9);
    }

    @Test
    public void testValue_NoBoundaries_Maximize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] decoded = {1.0, 2.0};
        double objectiveValue = 10.0;

        setField("boundaries", null);
        setField("isRepairMode", false);
        setField("isMinimize", false);

        doReturn(decoded).when(fitnessFunction).decode(point);
        when(mockOptimizer.computeObjectiveValue(decoded)).thenReturn(objectiveValue);

        double result = fitnessFunction.value(point);

        assertEquals(-objectiveValue, result, 1e-9);
    }

    @Test
    public void testValue_WithBoundaries_RepairMode_Minimize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] repaired = {1.5, 2.5};
        double[] decodedRepaired = {1.5, 2.5};
        double objectiveValue = 20.0;
        double penaltyValue = 5.0;

        setField("boundaries", new double[]{0.0, 5.0});
        setField("isRepairMode", true);
        setField("isMinimize", true);

        doReturn(repaired).when(fitnessFunction).repair(point);
        doReturn(decodedRepaired).when(fitnessFunction).decode(repaired);
        when(mockOptimizer.computeObjectiveValue(decodedRepaired)).thenReturn(objectiveValue);

        // Mocking penalty method via reflection or spy if possible. 
        // Since penalty is a method in the same class, we use spy.
        doReturn(penaltyValue).when(fitnessFunction).penalty(point, repaired);

        double result = fitnessFunction.value(point);

        assertEquals(objectiveValue + penaltyValue, result, 1e-9);
    }

    @Test
    public void testValue_WithBoundaries_RepairMode_Maximize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] repaired = {1.5, 2.5};
        double[] decodedRepaired = {1.5, 2.5};
        double objectiveValue = 20.0;
        double penaltyValue = 5.0;

        setField("boundaries", new double[]{0.0, 5.0});
        setField("isRepairMode", true);
        setField("isMinimize", false);

        doReturn(repaired).when(fitnessFunction).repair(point);
        doReturn(decodedRepaired).when(fitnessFunction).decode(repaired);
        when(mockOptimizer.computeObjectiveValue(decodedRepaired)).thenReturn(objectiveValue);
        doReturn(penaltyValue).when(fitnessFunction).penalty(point, repaired);

        double result = fitnessFunction.value(point);

        assertEquals(-(objectiveValue + penaltyValue), result, 1e-9);
    }

    @Test
    public void testValue_WithBoundaries_NoRepairMode_Minimize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] decoded = {1.0, 2.0};
        double objectiveValue = 15.0;

        setField("boundaries", new double[]{0.0, 5.0});
        setField("isRepairMode", false);
        setField("isMinimize", true);

        doReturn(decoded).when(fitnessFunction).decode(point);
        when(mockOptimizer.computeObjectiveValue(decoded)).thenReturn(objectiveValue);

        double result = fitnessFunction.value(point);

        assertEquals(objectiveValue, result, 1e-9);
        // Verify penalty was NOT called
        verify(fitnessFunction, org.mockito.Mockito.never()).penalty(any(), any());
    }
}
